@Test
fun evaluateTiming_tooSoon_roundsUpPartialMinute() {
    val mostRecentDose = DoseLog(
        id = 1,
        profileId = 1,
        medicationId = 1,
        givenAtEpochMillis = 0L,
        doseAmount = "5ml",
    )
    // Candidate is 30 seconds before the 60-minute mark -- should round up to 1 minute remaining.
    val candidate = 60 * 60_000L - 30_000L
    val result = DoseTimingCalculator.evaluateTiming(candidate, mostRecentDose, 60)
    assertTrue(result is DoseTimingResult.TooSoon)
    assertEquals(1L, (result as DoseTimingResult.TooSoon).minutesRemaining)
}
